  "subject" text,
  "customer_name" text,
  "customer_email" text,
  "assigned_to" uuid,
  "sentiment" text,
  "confidence_score" numeric(4,3),
  "resolution_type" text,
  "tags" text[] DEFAULT '{}'::text[],
  "metadata" jsonb DEFAULT '{}'::jsonb,
  "opened_at" timestamp with time zone DEFAULT now(),
  "resolved_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "csat_score" smallint,
  "csat_submitted_at" timestamp with time zone,
  CONSTRAINT conversations_channel_check CHECK ((channel = ANY (ARRAY['chat'::text, 'email'::text, 'phone'::text, 'api'::text]))),
  CONSTRAINT conversations_csat_score_check CHECK ((csat_score = ANY (ARRAY[1, '-1'::integer]))),
  CONSTRAINT conversations_resolution_type_check CHECK ((resolution_type = ANY (ARRAY['auto_resolved'::text, 'agent_assisted'::text, 'escalated'::text, 'unresolved'::text]))),
  CONSTRAINT conversations_sentiment_check CHECK ((sentiment = ANY (ARRAY['positive'::text, 'neutral'::text, 'negative'::text, 'urgent'::text]))),
  CONSTRAINT conversations_status_check CHECK ((status = ANY (ARRAY['open'::text, 'pending'::text, 'resolved'::text, 'escalated'::text, 'closed'::text]))),
