-- ── knowledge_articles ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.knowledge_articles (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "title" text NOT NULL,
  "body" text NOT NULL,
  "summary" text,
  "status" text DEFAULT 'draft'::text NOT NULL,
  "audience" text DEFAULT 'internal'::text NOT NULL,
  "category" text,
  "tags" text[] DEFAULT '{}'::text[],
  "product" text,
  "module" text,
  "quality_score" integer DEFAULT 0,
  "freshness_score" integer DEFAULT 100,
  "view_count" integer DEFAULT 0,
  "helpful_count" integer DEFAULT 0,
  "not_helpful_count" integer DEFAULT 0,
  "embedding" vector(1536),
  "created_by" uuid,
  "published_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now(),
  "updated_at" timestamp with time zone DEFAULT now(),
  "search_tsv" tsvector,
  CONSTRAINT knowledge_articles_audience_check CHECK ((audience = ANY (ARRAY['internal'::text, 'customer'::text, 'both'::text]))),
  CONSTRAINT knowledge_articles_freshness_score_check CHECK (((freshness_score >= 0) AND (freshness_score <= 100))),
  CONSTRAINT knowledge_articles_quality_score_check CHECK (((quality_score >= 0) AND (quality_score <= 100))),
  CONSTRAINT knowledge_articles_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'archived'::text]))),
  CONSTRAINT knowledge_articles_pkey PRIMARY KEY (id)
);

