-- ── Indexes ─────────────────────────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_tenants_parent_tenant_id ON public.tenants USING btree (parent_tenant_id);
CREATE INDEX IF NOT EXISTS escalations_conv_idx ON public.escalations USING btree (conversation_id);
CREATE INDEX IF NOT EXISTS escalations_tenant_status_idx ON public.escalations USING btree (tenant_id, status);
CREATE INDEX IF NOT EXISTS fin_documents_ws_idx ON public.fin_documents USING btree (workspace_id);
CREATE INDEX IF NOT EXISTS ka_embedding_idx ON public.knowledge_articles USING ivfflat (embedding vector_cosine_ops) WITH (lists='100');
CREATE INDEX IF NOT EXISTS knowledge_articles_search_tsv_idx ON public.knowledge_articles USING gin (search_tsv);

